import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"产品会客厅 | 没有项目管理经验，如何推动团队一起完成任务？","description":"","frontmatter":{},"headers":[{"level":2,"title":"【写在前面的话】","slug":"【写在前面的话】","link":"#【写在前面的话】","children":[]},{"level":2,"title":"【第三期问题】","slug":"【第三期问题】","link":"#【第三期问题】","children":[{"level":3,"title":"用户留言","slug":"用户留言","link":"#用户留言","children":[]}]},{"level":2,"title":"邱岳回信","slug":"邱岳回信","link":"#邱岳回信","children":[]},{"level":2,"title":"【精选分享】","slug":"【精选分享】","link":"#【精选分享】","children":[]},{"level":2,"title":"【课后问题】","slug":"【课后问题】","link":"#【课后问题】","children":[]}],"relativePath":"邱岳的产品实战/产品会客厅-没有项目管理经验，如何推动团队一起完成任务？.md","filePath":"邱岳的产品实战/产品会客厅-没有项目管理经验，如何推动团队一起完成任务？.md","lastUpdated":1779822594000}'),s={name:"邱岳的产品实战/产品会客厅-没有项目管理经验，如何推动团队一起完成任务？.md"};function r(l,e,p,o,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="产品会客厅-没有项目管理经验-如何推动团队一起完成任务" tabindex="-1">产品会客厅 | 没有项目管理经验，如何推动团队一起完成任务？ <a class="header-anchor" href="#产品会客厅-没有项目管理经验-如何推动团队一起完成任务" aria-label="Permalink to &quot;产品会客厅 | 没有项目管理经验，如何推动团队一起完成任务？&quot;">​</a></h1><h2 id="【写在前面的话】" tabindex="-1">【写在前面的话】 <a class="header-anchor" href="#【写在前面的话】" aria-label="Permalink to &quot;【写在前面的话】&quot;">​</a></h2><p>你好，我是邱岳。</p><p>产品会客厅是一个实战问答的板块，我想要创造的是一个集思广益、共同探讨问题、答疑解惑的互动环境。</p><p>在前三周的文章中，我们一起模拟了产品从规划到立项的整个过程。我根据自己的经验，试着总结了一些注意事项。</p><p>实际上，这些只是产品经理会面对的一小部分。当你真正地参与到这个过程中，你就会发现，无论前期准备得多么充分，规划得多么完美，难免还是会遇到各种各样、具体而琐碎的问题。</p><p>我也经常读到读者朋友给我的留言，大家会谈及一些在实际工作遇见的问题。很感谢朋友们对我的信任，只不过，简单的三言两语并不能完整地表述出我具体的处理方式和思考。</p><p>所以，我会在“产品会客厅”这个板块中，把一些具体的实战问题选出来。我和池老师会先给出一些自己的思考与解答，也希望更多的朋友可以加入我们，一起去尝试在更多的实战场景解答问题，共同成长和精进。</p><p>今天的这位同学遇见了一个问题。在产品从规划到发布的过程中，作为立项人，需要把握整个项目的节奏。 <strong>在一些需要推动产品工作进行的时刻，没有项目管理经验，应该注意哪些问题，又如何推动团队一起完成呢？</strong></p><p>无论是产品经理还是运营，只要你需要掌控项目整体的进度，就难免会需要在各个节点去推动事情的发生。那么说，怎样以自己的身份做好产品规划、立项并最终推进产品的实施和迭代呢。今天，我们就一起来看一看。</p><h2 id="【第三期问题】" tabindex="-1">【第三期问题】 <a class="header-anchor" href="#【第三期问题】" aria-label="Permalink to &quot;【第三期问题】&quot;">​</a></h2><p>恭喜第二期的幸运用户 @laulend™，你的提问被抽取成为本周的实战问题。极客时间将送出价值68元的极客福袋一份。1个工作日之内，工作人员会与你取得联系。</p><h3 id="用户留言" tabindex="-1">用户留言 <a class="header-anchor" href="#用户留言" aria-label="Permalink to &quot;用户留言&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/4bfd33d52f0c6a740daa94a7a316bd60.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/4bfd33d52f0c6a740daa94a7a316bd60.jpg" alt=""></a></p><h2 id="邱岳回信" tabindex="-1">邱岳回信 <a class="header-anchor" href="#邱岳回信" aria-label="Permalink to &quot;邱岳回信&quot;">​</a></h2><p>谢谢你的问题。</p><p>我想起来刚入行不久时的一件事，那时我跟着前辈一起做项目，在项目组中需要跟其他部门的产品经理协作，那个产品经理能力有一些问题，大家都不太喜欢他。我在一次公开场合很不客气地挑起了跟他的冲突，说得他哑口无言。</p><p>事后，带着我做项目的前辈把我叫到一边，翻出公司发的笔记本，那个本子上的每一页上都印有不同的职场鸡汤，他翻了一会儿，找到一页指给我看，我清楚地记得，那一页上印的鸡汤是： <strong>“不要让自己的队友失败”。</strong></p><p>这个前辈慢条斯理地跟我说，那个产品经理有他的问题，我们都看到了，可我们现在是队友，不能让自己的队友失败。在心态上，你不应该想着打垮他或取代他，而是应该帮他。</p><p>我之所以想把这个故事讲给你听，是因为，从你的问题中我似乎读到了不安和抱怨。我不知道具体情况，所以没办法评价你问题中产品岗位上的同事。但我想不腰疼地给你第一个建议是，与其代替他做所有的事情，你不如想办法帮助他，让他负起自己的责任。</p><p>帮助一个人的方法有很多，比如提醒他，要求他，建议他，甚至换掉他，但我觉得，替他做事情并不是一个好方法。</p><p>你的 1、2、3、5 四个问题，在我的理解中是同一个问题，就是： <strong>怎样以运营的身份做好产品规划、立项并最终推进产品的实施和迭代。</strong></p><p>你在问题里提到怎样确定规范，把控环节，将流程打通。听起来你所在的公司或许没有一套强制执行的标准流程规范。那我的建议是，由你们自己讨论和商定项目流程。</p><p>你可以自己来做项目经理，召集大家一起讨论，将每个流程环节以及环节的产出物定义清楚。比如在你提出需求之后，需要产品经理和设计一起产出方案，可能是 PRD，也可能是原型图，甚至是白板草图和口头描述，不论是什么形式，根据团队的情况达成一致就好。</p><p>然后保证需求的提出方，也就是你自己，还有工程师都能对这一产出物有统一理解，然后投入开发，上线前由整个团队一起做简单的测试并发布。在讨论并达成一致的基础之上，这些环节可以跟大家协调分工，大家各司其职，各尽其能。</p><p>至于你的第4个问题： <strong>运营做立项人是否合适</strong>？我觉得合适。就像专栏开篇词提到的那样：并没有任何一件推动公司前进的事务能够泾渭分明地划分职能责任。</p><p>在问题的开头，你提到了自己作为立项人时，立项过程遇到的种种困难，这样的困难对其他的职能岗位来说也是一样的，甚至由于业务的不相通也许会更难。</p><p>而运营作为距离用户最近的人，也可以更敏锐地感知到用户需求，在与各个职能打交道的时候，也可以及时调整产品的细节。</p><p>我从你问题的描述中，能感受到你想把事情做成的热情，这股热情如果能成为支撑你主动承担更多责任，解决团队问题的驱动力，或许你会有更多意想不到的收获。你在问题中提到付出，包括付出更多精力和时间，我相信这些付出终会是值得的，希望你能再坚持一下。</p><p>谢谢你的支持，希望这个回答能带给你一点启发，祝你的工作早日变得顺心起来。</p><p>邱岳</p><p>2018.08.24</p><h2 id="【精选分享】" tabindex="-1">【精选分享】 <a class="header-anchor" href="#【精选分享】" aria-label="Permalink to &quot;【精选分享】&quot;">​</a></h2><p>恭喜用户@刘祯 @ qc精灵鼠 的留言被选为精选分享，极客时间将为你送出价值68元的极客福袋一份。一个工作日之内，工作人员会与你取得联系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/7385a2c5c3a52d41cbba01793d4c0294.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/7385a2c5c3a52d41cbba01793d4c0294.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/ff32e4cc1f6550403f12b526066fc0f2.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/ff32e4cc1f6550403f12b526066fc0f2.jpg" alt=""></a></p><h2 id="【课后问题】" tabindex="-1">【课后问题】 <a class="header-anchor" href="#【课后问题】" aria-label="Permalink to &quot;【课后问题】&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/ca44ece4ebd93c8fcb758140f2cdac66.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%82%B1%E5%B2%B3%E7%9A%84%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%98/images/13985/ca44ece4ebd93c8fcb758140f2cdac66.jpg" alt=""></a></p>',38)])])}const d=t(s,[["render",r]]);export{g as __pageData,d as default};
